<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111210"><title><?= e($title) ?> • Alma Alvinegra</title><link rel="icon" href="/assets/crest.png"><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/auth.css"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800&family=DM+Sans:wght@400;500;600;700&display=swap" rel="stylesheet"><script src="/auth.js" defer></script></head><body class="account-site"><a class="skip" href="#conteudo">Pular para o conteúdo</a><header class="account-header"><a class="brand" href="/"><img src="/assets/crest.png" width="38" height="46" alt="Escudo do Santos"><span>SANTOS FC<small>ALMA ALVINEGRA</small></span></a><nav aria-label="Menu da conta"><a href="/">← Voltar ao site</a><?php if($user): ?><a href="/conta.php">Minha conta</a><?php if($user['role']==='admin'): ?><a href="/admin.php">Administração</a><?php endif; ?><form action="/sair.php" method="post"><?= csrf_field() ?><button class="nav-logout">Sair ↗</button></form><?php endif; ?></nav></header>
