function error_box(?string $error): void { if ($error): ?><div class="form-message error" role="alert"><?= e($error) ?></div><?php endif; }
function password_field(string $name, string $label, string $autocomplete = 'new-password'): void { ?>
<label for="<?= e($name) ?>"><?= e($label) ?></label><div class="password-wrap"><input id="<?= e($name) ?>" type="password" name="<?= e($name) ?>" autocomplete="<?= e($autocomplete) ?>" required maxlength="72" <?= $autocomplete==='new-password'?'minlength="12"':'' ?>><button type="button" class="reveal-password" data-password="<?= e($name) ?>" aria-label="Mostrar <?= e(strtolower($label)) ?>" aria-pressed="false">Mostrar</button></div>
<?php }
